corrected_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;

// routes/channels.php
Broadcast::channel('chat.conversation.{conversationId}', function (User $user, int $conversationId) {
    return $user->conversations()
        ->where('conversations.id', $conversationId)
        ->exists();
});
